INSERT INTO `pages` (`id`, `slug`, `title_en`, `title_fr`, `title_ar`, `subtitle_en`, `subtitle_fr`, `subtitle_ar`, `content_en`, `content_fr`, `content_ar`, `created_at`, `updated_at`) VALUES
(1, 'about', 'About Souk AI', 'À propos de Souk AI', 'عن سوق أي آي', 'Your Premium Marketplace', 'Votre marché premium', 'سوقك المتميز', 'Souk AI is a revolutionary AI-powered marketplace connecting exceptional sellers with discerning buyers across North Africa. Our platform combines cutting-edge technology with the rich tradition of commerce in the region.', 'Souk AI est un marché révolutionnaire propulsé par l\'intelligence artificielle, connectant des vendeurs exceptionnels avec des acheteurs exigeants à travers l\'Afrique du Nord. Notre plateforme allie une technologie de pointe à la riche tradition commerciale de la région.', 'سوق أي آي هو سوق ثوري مدعوم بالذكاء الاصطناعي يربط بين البائعين الاستثنائيين والمشترين المميزين في جميع أنحاء شمال أفريقيا. منصتنا تجمع بين أحدث التقنيات والتقاليد التجارية الغنية في المنطقة.', '2026-08-24 10:17:18', '2026-08-24 10:17:18'),
(2, 'contact', 'Get in Touch', 'Contactez-nous', 'تواصل معنا', 'We\'d love to hear from you', 'Nous serions ravis d\'avoir de vos nouvelles', 'نحب أن نسمع منك', 'Have questions, suggestions, or want to partner with us? Reach out and our team will get back to you within 24 hours.', 'Des questions, des suggestions ou envie de devenir partenaire ? Contactez-nous et notre équipe vous répondra dans les 24 heures.', 'هل لديك أسئلة أو اقتراحات أو تريد الشراكة معنا؟ تواصل معنا وسيرد فريقنا عليك خلال 24 ساعة.', '2026-08-24 10:17:18', '2026-08-24 10:17:18');
